messages.content:
{
  "title": "functions.expression.AnyOfInputSchema",
  "description": "Schema for a union of possible types - input must match at least one.",
  "type": "object",
  "properties": {
    "anyOf": {
      "description": "The possible schemas that the input can match.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.InputSchema"
      }
    }
  }
}

{
  "title": "functions.expression.FileInputSchema",
  "description": "Schema for a file input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected file.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.FileInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.InputValue",
  "description": "A concrete input value (post-compilation).\n\nRepresents any JSON-like value that can be passed to a Function,\nincluding rich content types (images, audio, video, files).",
  "anyOf": [
    {
      "title": "RichContentPart",
      "description": "Rich content (image, audio, video, file).",
      "$ref": "agent.completions.message.RichContentPart"
    },
    {
      "title": "Object",
      "description": "An object with string keys.",
      "type": "object",
      "additionalProperties": {
        "$ref": "functions.expression.InputValue"
      }
    },
    {
      "title": "Array",
      "description": "An array of values.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.InputValue"
      }
    },
    {
      "title": "String",
      "description": "A string value.",
      "type": "string"
    },
    {
      "title": "Integer",
      "description": "An integer value.",
      "type": "integer",
      "minimum": -9223372036854775808,
      "maximum": 9223372036854775807
    },
    {
      "title": "Number",
      "description": "A floating-point number.",
      "type": "number",
      "minimum": -3.4028234663852886e+38,
      "maximum": 3.4028234663852886e+38
    },
    {
      "title": "Boolean",
      "description": "A boolean value.",
      "type": "boolean"
    }
  ]
}

{
  "title": "functions.expression.Special",
  "description": "Predefined expression behaviors that require no user-authored code.",
  "anyOf": [
    {
      "title": "Input",
      "description": "Returns the params input as-is.",
      "type": "string",
      "enum": [
        "input"
      ]
    },
    {
      "title": "Output",
      "description": "Returns the params output as-is.",
      "type": "string",
      "enum": [
        "output"
      ]
    },
    {
      "title": "TaskOutputL1Normalized",
      "description": "L1-normalizes the output. Scalar/Err pass through.\nVector: L1 normalize. Vectors: L1 normalize each.",
      "type": "string",
      "enum": [
        "task_output_l1_normalized"
      ]
    },
    {
      "title": "TaskOutputWeightedSum",
      "description": "Weighted sum of the output. Vector → Scalar. Vectors → Vector.",
      "type": "string",
      "enum": [
        "task_output_weighted_sum"
      ]
    },
    {
      "title": "InputItemsOutputLength",
      "description": "Returns the length of input['items'] as u64",
      "type": "string",
      "enum": [
        "input_items_output_length"
      ]
    },
    {
      "title": "InputItemsOptionalContextSplit",
      "description": "Splits an input containing items and optionally context into multiple inputs",
      "type": "string",
      "enum": [
        "input_items_optional_context_split"
      ]
    },
    {
      "title": "InputItemsOptionalContextMerge",
      "description": "Merges multiple inputs containing items and optionally context into a single input",
      "type": "string",
      "enum": [
        "input_items_optional_context_merge"
      ]
    }
  ]
}

{
  "title": "agent.completions.message.ImageUrlDetail",
  "description": "Detail level for image processing.",
  "anyOf": [
    {
      "title": "Auto",
      "description": "Let the model decide the detail level.",
      "type": "string",
      "enum": [
        "auto"
      ]
    },
    {
      "title": "Low",
      "description": "Low detail mode (faster, less tokens).",
      "type": "string",
      "enum": [
        "low"
      ]
    },
    {
      "title": "High",
      "description": "High detail mode (more accurate, more tokens).",
      "type": "string",
      "enum": [
        "high"
      ]
    }
  ]
}

{
  "title": "agent.completions.message.File",
  "description": "A file attachment for multimodal input.",
  "type": "object",
  "properties": {
    "file_data": {
      "description": "Base64-encoded file data.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "file_id": {
      "description": "The ID of a previously uploaded file.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "file_url": {
      "description": "A URL to fetch the file from.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "filename": {
      "description": "The filename for display purposes.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    }
  }
}

{
  "title": "functions.expression.StringInputSchema",
  "description": "Schema for a string input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the string.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "enum": {
      "description": "If provided, the string must be one of these values.",
      "anyOf": [
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.StringInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.Expression",
  "description": "An expression that can be either JMESPath or Starlark.\n\nSerializes as `{\"$jmespath\": \"...\"}` or `{\"$starlark\": \"...\"}` in JSON.\n\n# Examples\n\nJMESPath:\n```json\n{\"$jmespath\": \"input.items[0].name\"}\n```\n\nStarlark:\n```json\n{\"$starlark\": \"input['items'][0]['name']\"}\n```",
  "anyOf": [
    {
      "title": "JMESPath",
      "description": "A JMESPath expression.",
      "type": "object",
      "properties": {
        "$jmespath": {
          "type": "string"
        }
      },
      "additionalProperties": false
    },
    {
      "title": "Starlark",
      "description": "A Starlark expression.",
      "type": "object",
      "properties": {
        "$starlark": {
          "type": "string"
        }
      },
      "additionalProperties": false
    },
    {
      "title": "Special",
      "description": "A predefined special expression variant.",
      "type": "object",
      "properties": {
        "$special": {
          "$ref": "functions.expression.Special"
        }
      },
      "additionalProperties": false
    }
  ]
}

{
  "title": "functions.expression.InputValue",
  "description": "A concrete input value (post-compilation).\n\nRepresents any JSON-like value that can be passed to a Function,\nincluding rich content types (images, audio, video, files).",
  "anyOf": [
    {
      "title": "RichContentPart",
      "description": "Rich content (image, audio, video, file).",
      "$ref": "agent.completions.message.RichContentPart"
    },
    {
      "title": "Object",
      "description": "An object with string keys.",
      "type": "object",
      "additionalProperties": {
        "$ref": "functions.expression.InputValue"
      }
    },
    {
      "title": "Array",
      "description": "An array of values.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.InputValue"
      }
    },
    {
      "title": "String",
      "description": "A string value.",
      "type": "string"
    },
    {
      "title": "Integer",
      "description": "An integer value.",
      "type": "integer",
      "minimum": -9223372036854775808,
      "maximum": 9223372036854775807
    },
    {
      "title": "Number",
      "description": "A floating-point number.",
      "type": "number",
      "minimum": -3.4028234663852886e+38,
      "maximum": 3.4028234663852886e+38
    },
    {
      "title": "Boolean",
      "description": "A boolean value.",
      "type": "boolean"
    }
  ]
}
